\label{I.8.3a}
If $\Ric(x,t_0)\le(n-1)K$ on $B_{t_0}(x_0,r_0)$, then outside that ball
\begin{equation}d_t-\triangle d\ge-(n-1)\left({2\over3}Kr_0+r_0^{-1}\right)
\end{equation}
at $t_0$, in the barrier sense when necessary.
\end{lemma}

